const event = $input.first().json;
const action = event.action || event;
if (!action || action.type !== 'updateCard') return [];
const data = action.data || {};
const card = data.card || {};
const list = data.list || {};
const listAfter = data.listAfter || {};
const old = data.old || {};
const listBefore = data.listBefore || {};
const currentListId = list.id || listAfter.id;
const oldListId = old.idList || listBefore.id;
const TARGET_LIST = '646b8c9613dc4e7000f6657e';
if (currentListId !== TARGET_LIST) return [];
if (!oldListId || oldListId === TARGET_LIST) return [];
return [{ json: { cardId: card.id, cardShortId: card.idShort, cardShortLink: card.shortLink, movedFromListId: oldListId } }];

const card = $input.first().json;
const customFieldItems = card.customFieldItems || [];
const labels = card.labels || [];
const FIELD_IDS = {
  manualDeclValue: '69ff02de827000773aed11bc',
  nerdyFormsId: '67a1ffdba5fb813971f92d9c',
  finalProductionPrice: '69ef59d6cea033d41d2c478b',
  finalShippingPrice: '69ef59edc28eb4c6deb1f61b',
  trackingNumber: '69ef5a77cea033d41d2df139',
  art: '69d644102d51b2950054c5ac',
};
const ART_OPTIONS = { '69f9d4426d20c460ecd8ab16':'LNF', '69d644102d51b2950054c5ae':'3DF', '69d644102d51b2950054c5ad':'3DB', '69d644102d51b2950054c5af':'3DN', '69f9d446e239eb69e1ed2d19':'LB' };
const LABEL_CI_DELETED = '6a0adeac4b31249c6946a529';
const getFI = id => customFieldItems.find(c => c.idCustomField === id);
const getTN = it => !it || !it.value ? null : (it.value.text !== undefined ? it.value.text : null);
const getDD = (it, m, fb) => !it || !it.idValue ? fb : (m[it.idValue] || fb);
const getNum = it => { if (!it || !it.value || it.value.number === undefined) return null; const n = parseFloat(it.value.number); return Number.isFinite(n) ? n : null; };
const manualDeclRaw = getTN(getFI(FIELD_IDS.manualDeclValue));
const manualDeclValueRawStr = manualDeclRaw === null || manualDeclRaw === undefined ? '' : String(manualDeclRaw);
const manualDeclValueMagic = manualDeclValueRawStr === 'LÖSCHEN' ? 'LÖSCHEN' : manualDeclValueRawStr === 'RECHNUNG' ? 'RECHNUNG' : null;
const requestId = String(getTN(getFI(FIELD_IDS.nerdyFormsId)) || '').trim();
const alreadyCleaned = labels.some(l => l && l.id === LABEL_CI_DELETED);
const finalProductionPriceUsd = getNum(getFI(FIELD_IDS.finalProductionPrice));
const finalShippingPriceUsd = getNum(getFI(FIELD_IDS.finalShippingPrice));
const trackingRaw = getTN(getFI(FIELD_IDS.trackingNumber));
const trackingNumber = trackingRaw ? String(trackingRaw).trim() : '';
const productType = getDD(getFI(FIELD_IDS.art), ART_OPTIONS, 'LNF');
return [{ json: { cardId: card.id, cardShortId: card.idShort, cardShortLink: card.shortLink, cardName: card.name, cardUrl: card.shortUrl || card.url, manualDeclValueRaw: manualDeclValueRawStr, manualDeclValueMagic, alreadyCleaned, requestId, finalProductionPriceUsd, finalShippingPriceUsd, trackingNumber, productType, timestamp: new Date().toISOString() } }];

const parsed = $('RECHNUNG: Parse CI Invoice Info').first().json;
const masterData = $('RECHNUNG: Sheet Master Data').first().json;
const fx = $input.first().json;
const shipper = masterData.shipper || {};
const buyer = masterData.default_consignee || {};
const rate = Number(fx.rates && fx.rates.EUR) || 0;
const fxDate = fx.date || parsed.ciDateStr || new Date().toISOString().slice(0,10);
// Match W4 format: convert date to ISO timestamp (midnight local = UTC-2h in CET)
const rateDateISO = fxDate ? new Date(fxDate + 'T00:00:00+01:00').toISOString() : fxDate;
// Invoice date from CI date
const ciDateStr = parsed.ciDateStr || fxDate;
const ciDateParts = ciDateStr.split('-');
const invoiceDateObj = new Date(Number(ciDateParts[0]), Number(ciDateParts[1])-1, Number(ciDateParts[2]));
const invoiceDate = invoiceDateObj.toLocaleDateString('en-GB', { day: '2-digit', month: 'long', year: 'numeric' });
const invoiceNumber = parsed.supplierInvoiceNumber;
const productionUsd = Number(parsed.finalProductionPriceUsd) || 0;
const shippingUsd = Number(parsed.finalShippingPriceUsd) || 0;
const totalUsd = productionUsd + shippingUsd;
const totalEur = Math.round(totalUsd * rate * 100) / 100;
const productType = parsed.productType || 'LNF';
const itemCode = 'NT' + productType + '-' + parsed.cardShortId;
const tracking = parsed.trackingNumber || '';
const descByType = { LNF: 'Custom LED acrylic sign with LED strip mounted on acrylic backboard, for advertising use', '3DF': 'Custom 3D frontlit LED channel-letter sign with face illumination, for advertising use', '3DB': 'Custom 3D backlit LED sign for advertising use', LB: 'Custom LED lightbox sign with LED backlight and acrylic front, for advertising use', '3DN': 'Custom 3D non-lit sign for advertising use' };
const description = descByType[productType] || descByType.LNF;
const paymentInfo = 'Payment needs to be made once the goods are received and are of good quality\nBeneficiary Name Dongguan Best Advertising Sign Co., Ltd.\nBeneficiary account number 10151130658005\nCountry/Region Singapore\nSwift Code CHASSGSGXXX or CHASSGSG\nChangi City, Changi Business Park Central 1, Singapore\nBeneficiary Bank JPMorgan Chase Bank N.A., Singapore Branch\nBeneficiary Bank Address 168 Robinson Road, Capital Tower 17-00, Singapore 068912\nBank Code 7153\nBranch Code 001';
const trackingSuffix = tracking ? '_' + tracking.replace(/\s+/g,'') : '';
const filename = 'Supplier Invoice ' + invoiceNumber + trackingSuffix + '.pdf';
const invoice = {
  invoice_number: invoiceNumber,
  invoice_date: invoiceDate,
  payment_terms: 'Net 30',
  payment_information: paymentInfo,
  fx: { rate, date: rateDateISO, source: 'Reference rate published by the European Central Bank' },
  supplier: { company: shipper.company_name || 'Dongguan Best Advertising Sign Co., Ltd.', address_1: shipper.address_line_1 || '', address_2: shipper.address_line_2 || '', address_3: shipper.address_line_3 || '', country: shipper.country || 'CHINA', phone: shipper.phone || '' },
  buyer: { company: buyer.company_name || 'DARA NOVA GmbH', address_1: buyer.address_line_1 || '', address_2: buyer.address_line_2 || '', country: buyer.country || 'GERMANY', eori: buyer.eori || '', vat: buyer.vat || '', phone: buyer.phone || '', email: buyer.email || '' },
  rows: [{ invoice_number: invoiceNumber, trello_ref: String(parsed.cardShortId), tracking, item_code: itemCode, design_safe_label: 'Custom Sign', description, qty: 1, unit: 'piece', unit_price_usd: productionUsd, shipping_usd: shippingUsd, amount_usd: totalUsd, amount_eur: totalEur }]
};
return [{ json: { ...parsed, invoice, filename, invoiceNumber } }];

const prepared = $input.first().json || {};
const invoice = prepared.invoice || prepared;

const esc = value => String(value === null || value === undefined ? '' : value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;')
  .replace(/'/g, '&#039;');
const clean = value => String(value === null || value === undefined ? '' : value).trim();
const usdMoney = value => {
  const number = Number(value);
  const safe = Number.isFinite(number) ? number : 0;
  return safe.toLocaleString('en-US', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  }) + ' USD';
};
const eurMoney = value => {
  const number = Number(value);
  const safe = Number.isFinite(number) ? number : 0;
  return safe.toLocaleString('de-DE', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  }) + ' EUR';
};
const qty = value => {
  const number = Number(value);
  if (!Number.isFinite(number)) return '0';
  return number.toLocaleString('en-US', {
    minimumFractionDigits: number % 1 === 0 ? 0 : 2,
    maximumFractionDigits: 2,
  });
};
const roundMoney = value => {
  const number = Number(value);
  const safe = Number.isFinite(number) ? number : 0;
  return Math.round(safe * 100) / 100;
};
const lines = values => values
  .map(clean)
  .filter(Boolean)
  .map(esc)
  .join('<br>');
const sum = (rows, field) => rows.reduce((total, row) => total + (Number(row[field]) || 0), 0);

const rows = Array.isArray(invoice.rows) ? invoice.rows.map(row => ({
  ...row,
  unit_price_usd: Number(row.unit_price_usd) || 0,
  shipping_usd: Number(row.shipping_usd) || 0,
  amount_usd: Number(row.amount_usd) || 0,
  amount_eur: Number(row.amount_eur) || 0,
  qty: Number(row.qty) || 1,
})) : [];
const hideShippingColumn = invoice.hide_shipping_column === true;
const isServiceInvoice = invoice.layout === 'service_invoice' ||
  invoice.invoice_type === 'service_invoice' ||
  Array.isArray(invoice.service_allocation);

const supplier = invoice.supplier || {};
const buyer = invoice.buyer || {};
const supplierAddress = lines([
  supplier.address_1,
  supplier.address_2,
  supplier.address_3,
  supplier.country,
  supplier.phone ? 'Phone: ' + supplier.phone : '',
]);
const buyerAddress = lines([
  buyer.company,
  buyer.address_1,
  buyer.address_2,
  buyer.country,
  buyer.vat ? 'VAT: ' + buyer.vat : '',
  buyer.phone ? 'Phone: ' + buyer.phone : '',
  buyer.email ? 'E-Mail: ' + buyer.email : '',
]);

const rowsHtml = rows.map((row, index) => {
  const detail = [row.item_code, row.design_safe_label || row.design_category || 'Custom Sign'].filter(Boolean).join(' ');
  const shippingCell = hideShippingColumn ? '' : `<td class="amount">${usdMoney(row.shipping_usd)}</td>`;
  return `
  <tr>
    <td class="line-number">${index + 1}</td>
    <td class="description">
      <span class="strong">${esc(row.description)}</span>
      ${detail ? `<div class="small">${esc(detail)}</div>` : ''}
    </td>
    <td class="amount">${usdMoney(row.unit_price_usd)}</td>
    ${shippingCell}
    <td class="qty">${qty(row.qty)}</td>
    <td class="amount strong">${usdMoney(row.amount_usd)}</td>
  </tr>`;
}).join('');
const shippingHeader = hideShippingColumn ? '' : '<th class="amount">Shipping</th>';

const exchangeRate = Number(invoice.fx && invoice.fx.rate) || Number(invoice.exchange_rate_usd_eur) || 0;
const usesLineItemEurTotals = invoice.eur_total_mode === 'sum_of_line_items';
const exchangeNoteTitle = usesLineItemEurTotals ? '' : 'Exchange Rate';
const exchangeNote = usesLineItemEurTotals
  ? ''
  : lines([
      exchangeRate ? '1 USD = ' + exchangeRate.toFixed(5) + ' EUR' : '',
      invoice.exchange_rate_date || (invoice.fx && invoice.fx.date) ? 'Rate date: ' + clean(invoice.exchange_rate_date || (invoice.fx && invoice.fx.date)) : '',
      invoice.exchange_rate_source || (invoice.fx && invoice.fx.source) ? clean(invoice.exchange_rate_source || (invoice.fx && invoice.fx.source)) : '',
    ]);

const paymentInformation = lines((invoice.payment_information || '').split(/\r?\n/));
const totalUsd = roundMoney(sum(rows, 'amount_usd'));
const totalEur = roundMoney(sum(rows, 'amount_eur'));

if (isServiceInvoice) {
  const servicePeriod = clean(invoice.service_period || [
    invoice.period_start,
    invoice.period_end,
  ].map(clean).filter(Boolean).join(' to '));
  const serviceLinePeriod = clean(invoice.service_period_label || invoice.service_month || invoice.month_label || servicePeriod);
  const documentTitle = clean(invoice.document_title || 'INVOICE');
  const discountUsd = roundMoney(invoice.discount_usd);
  const discountEur = roundMoney(invoice.discount_eur);
  const netUsd = roundMoney(invoice.invoice_total_usd || Math.max(0, totalUsd - discountUsd));
  const netEur = roundMoney(invoice.invoice_total_eur || Math.max(0, totalEur - discountEur));
  const vatId = clean(buyer.vat || invoice.buyer_vat || '');
  const discountDisplay = discountUsd > 0 ? '-' + usdMoney(discountUsd) : usdMoney(0);
  const serviceRowsHtml = rows.map((row, index) => {
    const rowPeriod = clean(row.period || row.service_period || serviceLinePeriod || invoice.invoice_date || '');
    return `
  <tr>
    <td class="service-number">${String(index + 1).padStart(2, '0')}</td>
    <td class="service-description">
      <span class="service-name">${esc(row.description)}</span>
    </td>
    <td class="service-period">${esc(rowPeriod)}</td>
    <td class="service-amount">${usdMoney(row.amount_usd)}</td>
  </tr>`;
  }).join('');
  const serviceSummary = lines([
    serviceLinePeriod ? 'Billing period: ' + serviceLinePeriod : (servicePeriod ? 'Billing period: ' + servicePeriod : ''),
  ]);
  const serviceHtml = `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <title>${esc(documentTitle)} ${esc(invoice.invoice_number)}</title>
  <style>
    @page {
      size: A4 portrait;
      margin: 13mm 12mm;
    }
    * { box-sizing: border-box; }
    body {
      margin: 0;
      font-family: Verdana, Geneva, Tahoma, sans-serif;
      color: #202426;
      background: #fff;
      font-size: 7.9pt;
      line-height: 1.32;
    }
    .page { min-height: 271mm; display: flex; flex-direction: column; }
    .topline {
      display: grid;
      grid-template-columns: 1fr 62mm;
      gap: 13mm;
      padding-bottom: 5mm;
      border-bottom: 0.8pt solid #202426;
    }
    .issuer-title {
      font-size: 7pt;
      text-transform: uppercase;
      letter-spacing: 1.2pt;
      color: #5d6367;
      margin-bottom: 2.5mm;
    }
    .issuer-name {
      font-size: 15pt;
      font-weight: 700;
      letter-spacing: 0;
      margin-bottom: 2mm;
    }
    .issuer-address {
      font-size: 8pt;
      line-height: 1.35;
      color: #343a3e;
    }
    .doc-panel {
      border: 0;
      border-top: 1.05pt solid #202426;
      padding: 3mm 0 2.7mm;
      min-height: 0;
    }
    .doc-title {
      font-size: 17pt;
      font-weight: 700;
      letter-spacing: 1pt;
      text-align: right;
      margin-bottom: 1.7mm;
    }
    .doc-number {
      font-size: 8.5pt;
      font-weight: 700;
      text-align: right;
      word-break: break-word;
      padding-bottom: 2mm;
      border-bottom: 0.55pt solid #c7cbce;
    }
    .doc-meta {
      margin-top: 2.2mm;
      display: grid;
      grid-template-columns: 1fr;
      gap: 1.2mm;
      text-align: right;
    }
    .doc-meta strong {
      display: block;
      margin-top: 0.8mm;
      font-size: 7.8pt;
    }
    .label {
      text-transform: uppercase;
      letter-spacing: 0.9pt;
      font-size: 6.4pt;
      color: #646b70;
      font-weight: 700;
    }
    .party-row {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 8mm;
      margin-top: 5mm;
      margin-bottom: 4.5mm;
    }
    .party-box {
      border-left: 0.8pt solid #202426;
      padding-left: 3mm;
      min-height: 29mm;
    }
    .party-content {
      margin-top: 1.8mm;
      font-size: 8pt;
      line-height: 1.35;
    }
    .facts {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      border-top: 0.7pt solid #9aa0a4;
      border-bottom: 0.7pt solid #9aa0a4;
      margin-bottom: 6mm;
    }
    .fact {
      padding: 2.1mm 2mm;
      border-right: 0.7pt solid #d0d4d7;
      min-height: 13mm;
    }
    .fact:last-child { border-right: 0; }
    .fact-value {
      margin-top: 1mm;
      font-weight: 700;
      font-size: 8pt;
    }
    table {
      width: 100%;
      border-collapse: collapse;
      table-layout: fixed;
    }
    thead { display: table-header-group; }
    tr { break-inside: avoid; }
    th {
      background: #e7e9ea;
      color: #202426;
      font-size: 6.4pt;
      text-transform: uppercase;
      letter-spacing: 0.7pt;
      padding: 1.8mm 1.3mm;
      text-align: left;
      border-top: 0.8pt solid #202426;
      border-bottom: 0.8pt solid #202426;
    }
    td {
      border-bottom: 0.55pt solid #c7cbce;
      padding: 1.35mm 1.2mm;
      vertical-align: top;
      font-size: 6.9pt;
    }
    .service-number { width: 11mm; color: #5d6367; }
    .service-description { width: auto; }
    .service-name { font-weight: 700; }
    .service-period { width: 31mm; color: #343a3e; }
    .service-amount {
      width: 27mm;
      text-align: right;
      white-space: nowrap;
      font-weight: 700;
    }
    .closing {
      display: grid;
      grid-template-columns: 1fr 72mm;
      gap: 10mm;
      margin-top: 7mm;
      align-items: start;
      break-inside: avoid;
    }
    .statement-note {
      font-size: 7.2pt;
      color: #454b4f;
      line-height: 1.4;
    }
    .totals-box {
      border-top: 1pt solid #202426;
      padding-top: 2mm;
    }
    .total-line {
      display: grid;
      grid-template-columns: 1fr 25mm;
      gap: 4mm;
      padding: 1.5mm 0;
      border-bottom: 0.55pt solid #c7cbce;
    }
    .total-line.main {
      border-bottom: 1pt solid #202426;
      font-size: 9pt;
      font-weight: 700;
    }
    .total-line.eur-line {
      border-bottom: 0;
    }
    .tax-note { font-size: 6.3pt; color: #555d62; }
    .total-value { text-align: right; white-space: nowrap; }
    .service-footer {
      margin-top: auto;
      padding-top: 2.6mm;
      border-top: 0.8pt solid #202426;
      display: grid;
      grid-template-columns: 40mm 1fr;
      gap: 6mm;
      break-inside: avoid;
    }
    .service-footer-text {
      columns: 2;
      column-gap: 7mm;
      color: #202426;
      font-size: 6.4pt;
      line-height: 1.24;
    }
  </style>
</head>
<body>
  <main class="page">
    <section class="topline">
      <div>
        <div class="issuer-title">Issued by</div>
        <div class="issuer-name">${esc(supplier.company || 'Shenzhen Beister Advertising Logo Co., Ltd.')}</div>
        <div class="issuer-address">${supplierAddress}</div>
      </div>
      <div class="doc-panel">
        <div class="doc-title">${esc(documentTitle)}</div>
        <div class="doc-number">${esc(invoice.invoice_number)}</div>
        <div class="doc-meta">
          <div><span class="label">Currency</span><strong>USD</strong></div>
          <div><span class="label">Date</span><strong>${esc(invoice.invoice_date)}</strong></div>
        </div>
      </div>
    </section>

    <section class="party-row">
      <div class="party-box">
        <div class="label">Client</div>
        <div class="party-content">${buyerAddress}</div>
      </div>
      <div class="party-box">
        <div class="label">Statement</div>
        <div class="party-content">${serviceSummary || 'Professional services supplied as listed below.'}</div>
      </div>
    </section>

    <table>
      <thead>
        <tr>
          <th class="service-number">Pos.</th>
          <th class="service-description">Description of Work</th>
          <th class="service-period">Period</th>
          <th class="service-amount">Amount</th>
        </tr>
      </thead>
      <tbody>
        ${serviceRowsHtml}
      </tbody>
    </table>

    <section class="closing">
      <div class="statement-note">
        <div class="label">Notes</div>
        Positions listed above are billed as professional support, preparation, handling, inspection and coordination services.
      </div>
      <div class="totals-box">
        <div class="total-line">
          <div>Subtotal</div>
          <div class="total-value">${usdMoney(totalUsd)}</div>
        </div>
        <div class="total-line">
          <div>Discount</div>
          <div class="total-value">${discountDisplay}</div>
        </div>
        <div class="total-line">
          <div>VAT 0%${vatId ? ` <span class="tax-note">(VAT ID: ${esc(vatId)})</span>` : ''}</div>
          <div class="total-value">${usdMoney(0)}</div>
        </div>
        <div class="total-line main">
          <div>Total Due</div>
          <div class="total-value">${usdMoney(netUsd)}</div>
        </div>
        <div class="total-line eur-line">
          <div></div>
          <div class="total-value">${eurMoney(netEur)}</div>
        </div>
      </div>
    </section>

    <footer class="service-footer">
      <div class="label">Payment Information</div>
      <div class="service-footer-text">${paymentInformation || 'Payment details to be provided by the issuer.'}</div>
    </footer>
  </main>
</body>
</html>`;

  return [{
    json: {
      ...prepared,
      rendered_html: serviceHtml,
      filename: prepared.filename || 'service-invoice-' + clean(invoice.invoice_number || 'draft') + '.pdf',
    },
  }];
}

const html = `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <title>Supplier Invoice ${esc(invoice.invoice_number)}</title>
  <style>
    @page {
      size: A4 portrait;
      margin: 10mm;

      @bottom-right {
        content: counter(page) "/" counter(pages);
        font-family: Arial, Helvetica, sans-serif;
        font-size: 7pt;
        color: #111827;
      }
    }
    * { box-sizing: border-box; }
    body {
      margin: 0;
      font-family: Arial, Helvetica, sans-serif;
      color: #111827;
      background: #fff;
      font-size: 8pt;
      line-height: 1.25;
    }
    .page { min-height: 277mm; display: flex; flex-direction: column; }
    .header {
      display: grid;
      grid-template-columns: 1fr 62mm;
      gap: 10mm;
      padding-bottom: 5mm;
      border-bottom: 1.4pt solid #111827;
    }
    .supplier-name {
      font-size: 13pt;
      font-weight: 800;
      margin-bottom: 2mm;
      color: #111827;
    }
    .document-title {
      text-align: right;
      font-size: 25pt;
      font-weight: 800;
      letter-spacing: 0;
    }
    .document-number {
      text-align: right;
      margin-top: 1mm;
      font-size: 10pt;
      font-weight: 800;
      color: #111827;
    }
    .party-grid {
      width: 96mm;
      margin-top: 6mm;
      margin-bottom: 5mm;
    }
    .block-label {
      text-transform: uppercase;
      color: #6b7280;
      font-size: 6.8pt;
      font-weight: 800;
      margin-bottom: 1.5mm;
    }
    .billto-box {
      border: 0.7pt solid #d1d5db;
      padding: 3mm;
      min-height: 28mm;
    }
    .meta {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      border: 0.7pt solid #d1d5db;
      margin-bottom: 5mm;
    }
    .meta-cell {
      padding: 2mm;
      border-right: 0.7pt solid #d1d5db;
      min-height: 13mm;
    }
    .meta-cell:last-child { border-right: 0; }
    .meta-label {
      color: #6b7280;
      font-size: 6.5pt;
      text-transform: uppercase;
      font-weight: 800;
      margin-bottom: 1mm;
