const attachments = $input.all().map(i => i.json);
const parsed = $('Parse + Check LÖSCHEN').first().json;
// Find CI PDF: 'commercial invoice YYYYMMDD-cardId-NNNN_v1.pdf'
const ciPattern = /commercial invoice (\d{8}-\d+-\d{4})_v1/i;
let ciInvoiceNumber = null;
let ciDateStr = null;
for (const att of attachments) {
  const match = ciPattern.exec(att.name || '');
  if (match) { ciInvoiceNumber = match[1]; break; }
}
if (ciInvoiceNumber) {
  const d = ciInvoiceNumber.slice(0, 8);
  ciDateStr = d.slice(0,4) + '-' + d.slice(4,6) + '-' + d.slice(6,8);
}
// Fallback: today
const now = new Date();
const fallbackDate = now.toISOString().slice(0,10);
return [{ json: {
  ...parsed,
  ciInvoiceNumber,
  ciDateStr: ciDateStr || fallbackDate,
  supplierInvoiceNumber: ciInvoiceNumber ? 'INV-' + ciInvoiceNumber : 'INV-' + now.toISOString().slice(0,10).replace(/-/g,'') + '-' + parsed.cardShortId,
} }];
